import numpy as npfrom abc import ABC, abstractmethod class AcousticElement(ABC):    """Base class for any element of the acoustic network (duct, boundary...).    Every element must implement transfer_matrix(omega), which returns the    2x2 matrix T such that [p, u]_out = T @ [p, u]_in, where p and u are    the acoustic pressure and acoustic velocity.    """    @abstractmethod    def transfer_matrix(self, omega):        pass        class Duct(AcousticElement):    """A straight duct of uniform cross-section, with no mean flow and no losses."""        def __init__(self, length, speed_of_sound):        """Store the duct's physical properties (length, speed of sound, density)."""                self.length = length        self.speed_of_sound =speed_of_sound        self.density = 1.2        self.Z = self.speed_of_sound * self.density            def transfer_matrix(self, omega):        """Return the 2x2 transfer matrix relating [p, u] at the inlet to [p, u] at the outlet, for a given angular frequency omega."""                k = omega / self.speed_of_sound        kL = k * self.length                T = np.array([[np.cos(kL), -1j * self.Z * np.sin(kL)],                     [(-1j * np.sin(kL)) / self.Z, np.cos(kL)]], dtype=np.complex128)                return T         class BoundaryCondition(ABC):    """Base class for a boundary condition of the form a*p + b*u = 0.    Every boundary condition must implement coefficients(), which returns    the pair (a, b) defining the constraint on the acoustic state [p, u]    at that end of the network.    """    @abstractmethod    def coefficients(self):        pass        class ClosedEnd(BoundaryCondition):    """Rigid wall: the acoustic velocity is zero (u = 0)."""        def coefficients(self):        """Return (a, b) such that a*p + b*u = 0, i.e. u = 0 at a rigid wall."""                return (0.0, 1.0)    class OpenEnd(BoundaryCondition):    """Open end, idealized (no end correction, no radiation impedance): p = 0."""        def coefficients(self):        """Return (a, b) such that a*p + b*u = 0, i.e. p = 0 at an idealized open end."""                return (1.0, 0.0)    